CREATE TABLE public.permission_support_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.staff_permission_requests(id), reviewer_id uuid NOT NULL, note text NOT NULL CHECK(length(note) BETWEEN 5 AND 500), requested_at timestamptz NOT NULL DEFAULT now(), response_path text, responded_at timestamptz);
GRANT SELECT ON public.permission_support_requests TO authenticated;
GRANT ALL ON public.permission_support_requests TO service_role;
ALTER TABLE public.permission_support_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_participants_read ON public.permission_support_requests FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.staff_permission_requests r WHERE r.id=request_id AND (r.requester_id=auth.uid() OR public.can_review_permissions(r.institution_id))));
CREATE FUNCTION public.request_permission_support(_id uuid,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.staff_permission_requests; sid uuid; BEGIN SELECT * INTO r FROM public.staff_permission_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.requester_id=auth.uid() OR NOT coalesce(public.can_review_permissions(r.institution_id),false) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; IF r.status<>'pendiente' THEN RAISE EXCEPTION 'Solo solicitudes pendientes'; END IF; IF EXISTS(SELECT 1 FROM public.permission_support_requests WHERE request_id=_id AND responded_at IS NULL) THEN RAISE EXCEPTION 'Ya hay un respaldo pendiente'; END IF; INSERT INTO public.permission_support_requests(request_id,reviewer_id,note) VALUES(_id,auth.uid(),btrim(_note)) RETURNING id INTO sid; RETURN sid; END $$;
CREATE FUNCTION public.respond_permission_support(_id uuid,_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,storage AS $$ DECLARE s public.permission_support_requests; r public.staff_permission_requests; BEGIN SELECT * INTO s FROM public.permission_support_requests WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; SELECT * INTO r FROM public.staff_permission_requests WHERE id=s.request_id FOR UPDATE; IF r.requester_id IS DISTINCT FROM auth.uid() OR r.status<>'pendiente' OR s.responded_at IS NOT NULL THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; IF split_part(_path,'/',1) IS DISTINCT FROM auth.uid()::text OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='permission-attachments' AND name=_path) THEN RAISE EXCEPTION 'Archivo propio no encontrado'; END IF; UPDATE public.permission_support_requests SET response_path=_path,responded_at=now() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.request_permission_support(uuid,text), public.respond_permission_support(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.request_permission_support(uuid,text), public.respond_permission_support(uuid,text) TO authenticated;
CREATE POLICY support_reviewer_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='permission-attachments' AND EXISTS(SELECT 1 FROM public.permission_support_requests s JOIN public.staff_permission_requests r ON r.id=s.request_id WHERE s.response_path=name AND (r.requester_id=auth.uid() OR public.can_review_permissions(r.institution_id))));
CREATE TABLE public.account_role_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,actor_id uuid NOT NULL,previous_roles text[] NOT NULL,new_role text NOT NULL,changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_role_events TO authenticated;
GRANT ALL ON public.account_role_events TO service_role;
ALTER TABLE public.account_role_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY max_role_history ON public.account_role_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.admin_correct_account_role(_user uuid,_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oldroles text[]; BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Solo Max' USING ERRCODE='42501'; END IF; IF _role NOT IN ('teacher','student') OR _user=auth.uid() OR public.has_role(_user,'admin') THEN RAISE EXCEPTION 'Cuenta o rol protegido' USING ERRCODE='42501'; END IF; PERFORM 1 FROM auth.users WHERE id=_user FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Cuenta no encontrada'; END IF; SELECT coalesce(array_agg(role::text),'{}'::text[]) INTO oldroles FROM public.user_roles WHERE user_id=_user; DELETE FROM public.user_roles WHERE user_id=_user AND role IN ('teacher','student'); INSERT INTO public.user_roles(user_id,role) VALUES(_user,_role::public.app_role); INSERT INTO public.account_role_events(user_id,actor_id,previous_roles,new_role) VALUES(_user,auth.uid(),oldroles,_role); END $$;
REVOKE ALL ON FUNCTION public.admin_correct_account_role(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_correct_account_role(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_institution_member(_inst uuid,_email text,_role public.institution_role) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; oldrole public.institution_role; BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Solo administración' USING ERRCODE='42501'; END IF; IF NOT EXISTS(SELECT 1 FROM public.institutions WHERE id=_inst) THEN RAISE EXCEPTION 'Institución no encontrada'; END IF; SELECT id INTO uid FROM auth.users WHERE lower(email)=lower(btrim(_email)) AND email_confirmed_at IS NOT NULL; IF uid IS NULL THEN RAISE EXCEPTION 'No existe una cuenta confirmada con ese correo'; END IF; SELECT member_role INTO oldrole FROM public.institution_members WHERE institution_id=_inst AND user_id=uid FOR UPDATE; INSERT INTO public.institution_members(institution_id,user_id,member_role,verified_by) VALUES(_inst,uid,_role,auth.uid()) ON CONFLICT(institution_id,user_id) DO UPDATE SET member_role=excluded.member_role,verified_by=auth.uid(); INSERT INTO public.institution_role_events(institution_id,actor_id,user_id,previous_role,new_role) VALUES(_inst,auth.uid(),uid,oldrole::text,_role::text); RETURN uid; END $$;